$ErrorActionPreference = 'Stop'
function AssetData([string]$name) {
  $mime = if ($name.EndsWith('.png')) { 'image/png' } else { 'image/jpeg' }
  return 'data:' + $mime + ';base64,' + [Convert]::ToBase64String([IO.File]::ReadAllBytes((Join-Path $PSScriptRoot ('assets/' + $name))))
}
$hero = AssetData 'hero-financas.jpg'
